    s.callout(AI, [('Describe the structure of stomata after microscopic observation of an epidermal peel of a leaf.', 'پتے کی اپی ڈرمس کی جھلی کا خردبین سے مشاہدہ کرنے کے بعد اسٹومیٹا کی ساخت بیان کریں۔', 'د پاڼې د اپیډرمس پوټکي له مایکروسکوپي کتنې وروسته د سټوماټا جوړښت بیان کړئ.'),
                   ('Investigate wilting in a potted plant.', 'گملے میں لگے پودے میں مرجھانے کی تحقیق کریں۔', 'په ګملي کې د بوټي مړاوي کېدل وڅېړئ.')])
